hl.bind(secondMod .. " + L", hl.dsp.window.move({ direction = "right" }))
hl.bind(secondMod .. " + I", hl.dsp.window.move({ direction = "up" }))
hl.bind(secondMod .. " + K", hl.dsp.window.move({ direction = "down" }))


