-- Hyprland-run windowrule
hl.window_rule({
  name  = "move-hyprland-run",
  match = { class = "hyprland-run" },

  move  = "20 monitor_h-120",
  float = true,
})

-- La ventana de ayuda (SUPER + A) sale flotante en vez de sumarse al mosaico.
hl.window_rule({
  name  = "ayuda-flotante",
  match = { title = "^ayuda-atajos$" },

  float = true,
})

-- Las TUI que abren los clics de Waybar (volumen, bluetooth, red, CPU, memoria) son
-- consultas puntuales que se cierran enseguida: salen flotantes para no reacomodar el
-- mosaico entero por una mirada de dos segundos.
--
-- El match va por TITULO y no por clase porque todas son la misma app (ghostty); lo
-- que las distingue es el '--title=' que les pasa cada on-click en waybar/config.jsonc.
-- Verificado que ese título sobrevive a la TUI: htop no lo pisa.
--
-- Sin 'center' ni 'size' a propósito: se deja que Hyprland las ubique y que cada una
-- conserve el tamaño que pide.
hl.window_rule({
  name  = "waybar-tui-flotantes",
  match = { title = "^(wiremix|bluetui|nmtui|htop|rclone-sync|rclone-log)$" },

  float = true,
})

-- btop va aparte porque necesita mucho más espacio que las otras: con el tamaño por
-- defecto de ghostty (800x600) se queja de que la terminal es chica y no dibuja sus
-- paneles.
--
-- OJO con el formato: 'size' sólo acepta una TABLA DE DOS NÚMEROS en píxeles lógicos.
-- Las variantes size = "80% 85%" y size = { "80%", "85%" } se aceptan sin error pero
-- NO hacen nada -- la ventana sale con el tamaño por defecto y uno no se entera.
-- Verificado probando las tres formas.
--
-- Píxeles lógicos (y no físicos) significa que el recuento de caracteres se mantiene
-- entre monitores con distinta escala, que es lo que le importa a btop.
hl.window_rule({
  name  = "btop-flotante-grande",
  match = { title = "^btop$" },

  float = true,
  size  = { 1024, 680 },
})
